"""Point helpers. A point is an (x, y) tuple of numbers."""

import math

Point = tuple[float, float]


def distance(p: Point, q: Point) -> float:
    """Straight-line (Euclidean) distance between two points."""
    return math.hypot(q[0] - p[0], q[1] - p[1])


def midpoint(p: Point, q: Point) -> Point:
    """The point halfway between p and q."""
    return ((p[0] + q[0]) / 2, (p[1] + q[1]) / 2)


def translate(p: Point, dx: float, dy: float) -> Point:
    """Move a point by dx along x and dy along y."""
    return (p[0] + dx, p[1] + dy)


def scale(p: Point, factor: float) -> Point:
    """Multiply both coordinates by factor."""
    return (p[0] * factor, p[1] * factor)

