from geokit.points import Point


class Rect:
    """An axis-aligned rectangle with its top-left corner at (x, y)."""

    def __init__(self, x: float, y: float, width: float, height: float) -> None:
        if width <= 0 or height <= 0:
            raise ValueError("width and height must be positive")
        self.x = x
        self.y = y
        self.width = width
        self.height = height

    def area(self) -> float:
        """Width times height."""
        return self.width * self.height

    def perimeter(self) -> float:
        """Length of the boundary."""
        return 2 * (self.width + self.height)

    def contains(self, p: Point) -> bool:
        """True when p lies inside; the right and bottom edges count as outside."""
        return self.x <= p[0] < self.x + self.width and self.y <= p[1] < self.y + self.height


class Polygon:
    """A simple polygon given its corners in order."""

    def __init__(self, points: list[Point]) -> None:
        self.points = list(points)

    def area(self) -> float:
        """Area by the shoelace formula."""
        total = 0.0
        for i, (x1, y1) in enumerate(self.points):
            x2, y2 = self.points[(i + 1) % len(self.points)]
            total += x1 * y2 - x2 * y1
        return abs(total) / 2


def polygon_area(points: list[Point]) -> float:
    """Area of a simple polygon given its corners in order (shoelace formula)."""
    return Polygon(points).area()

